    obs = observation.get("obstacles", [])
    sp = observation.get("self_path", [])
    op = observation.get("opponent_path", [])

    def pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            a, b = v[0], v[1]
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                return [int(a), int(b)]
        if isinstance(v, dict):
            if "x" in v and "y" in v:
                return [int(v["x"]), int(v["y"])]
            for k in ("pos", "position", "loc", "location", "xy", "coord", "coords"):
                if k in v:
                    p = pos(v[k])
                    if p is not None:
                        return p
        return None

    def gather(v):
        out = []
        if isinstance(v, dict):
            p = pos(v)
            if p is not None:
                out.append(p)
            else:
                for x in v.values():
                    out.extend(gather(x))
