            p = pos(v)
            if p is not None:
                out.append(p)
            else:
                for x in v:
                    out.extend(gather(x))
        return out

    r = gather(res)
    if not r:
        tx, ty = ox, oy
    else:
        tx, ty = min(r, key=lambda p: abs(p[0] - sx) + abs(p[1] - sy))

    dx = -1 if tx < sx else 1 if tx > sx else 0
    dy = -1 if ty < sy else 1 if ty > sy else 0

